+    }
+    catch {
+        Write-ColorMessage "Erreur lors du demarrage du modele $ModelName" $Red
+        Write-ColorMessage $_.Exception.Message $Red
+        return $false
+    }
+    finally {
+        Set-Location -Path $PSScriptRoot
+    }
+}
