+                # Vérifier si le conteneur est en cours d'exécution
+                if ($status -match "Up") {
+                    # Afficher les dernières lignes de log
+                    Write-ColorMessage "  Derniers logs:" $Magenta
+                    docker logs $containerName --tail 3 2>&1 | ForEach-Object { Write-Host "    $_" }
