+    
+    if ($All -or $Model1_7B) {
+        $result = Start-QwenModel -ModelPath "1.7b-awq" -ModelName "Qwen3 1.7B AWQ" -ContainerName "myia-vllm_vllm-qwen3-1.7b-awq"
+        $success = $success -and $result
