+    
+    Write-Log "INFO" "Déploiement des services vLLM Qwen3 avec la nouvelle image refactorisée terminé."
+    return 0
+}
+
+# Analyser les arguments de la ligne de commande
+$skipTests = $false
+$forceRestart = $false
+
+for ($i = 0; $i -lt $args.Count; $i++) {
+    switch ($args[$i]) {
+        "--skip-tests" {
+            $skipTests = $true
