+    # Utilisation de la mémoire GPU
+    $env:GPU_MEMORY_UTILIZATION_MICRO = "0.9"
+    $env:GPU_MEMORY_UTILIZATION_MINI = "0.9"
+    $env:GPU_MEMORY_UTILIZATION_MEDIUM = "0.9"
